import { AIProviderFactory, getDefaultProvider, SUPPORTED_PROVIDERS } from '../config/aiProviders.js';

/**
 * Middleware: extractAIProvider
 *
 * Reads optional AI provider configuration from request headers and attaches
 * an AI adapter instance to `req.aiProvider`.
 *
 * Headers consumed:
 *   X-AI-Provider  – provider name (gemini | openai | openrouter | groq)
 *   X-AI-Key       – the user's API key for the chosen provider
 *   X-AI-Model     – (optional) model name override
 *
 * Fallback behaviour:
 *   If no headers are supplied the server-side Gemini key (GEMINI_API_KEY)
 *   is used automatically, so existing behaviour is fully preserved.
 */
export const extractAIProvider = async (req, res, next) => {
  try {
    const providerHeader = req.headers['x-ai-provider'];
    const apiKeyHeader   = req.headers['x-ai-key'];
    const modelHeader    = req.headers['x-ai-model'];
    const baseUrlHeader  = req.headers['x-ai-base-url'];
    const openRouterKeyHeader = req.headers['x-openrouter-key'];

    // --- Case 1a: User supplies OpenRouter key via BYOK PKCE flow ---
    if (openRouterKeyHeader) {
      req.aiProvider = AIProviderFactory.create('openrouter', openRouterKeyHeader);
      req.aiProviderSource = 'user_openrouter_pkce';
      return next();
    }

    // --- Case 1: User supplies both provider + key via headers (Legacy/API fallback) ---
    if (providerHeader && apiKeyHeader) {
      const provider = providerHeader.toLowerCase().trim();

      if (!SUPPORTED_PROVIDERS.includes(provider)) {
        return res.status(400).json({
          success: false,
          error: `Unsupported AI provider "${providerHeader}". Supported: ${SUPPORTED_PROVIDERS.join(', ')}`,
        });
      }

      req.aiProvider = AIProviderFactory.create(provider, apiKeyHeader, modelHeader, baseUrlHeader);
      req.aiProviderSource = 'user_header';
      return next();
    }

    // --- Case 2: No custom headers – check for server-side fallback ---
    const envProvider = process.env.AI_PROVIDER || 'gemini';
    let envKey = null;

    if (envProvider === 'gemini') envKey = process.env.GEMINI_API_KEY;
    else if (envProvider === 'openai') envKey = process.env.OPENAI_API_KEY;
    else if (envProvider === 'groq') envKey = process.env.GROQ_API_KEY;
    else if (envProvider === 'openrouter') envKey = process.env.OPENROUTER_API_KEY;
    else if (envProvider === 'requesty') envKey = process.env.REQUESTY_API_KEY;

    if (envKey) {
      req.aiProvider = AIProviderFactory.create(envProvider, envKey);
      req.aiProviderSource = 'server_env';
      return next();
    }

    // --- Case 3: No custom headers and no env fallback – reject gracefully ---
    return res.status(403).json({
      success: false,
      error: 'API key is required. Please add your API key in Settings to use this feature.',
      requireApiKey: true
    });
  } catch (error) {
    console.error('AI provider middleware error:', error.message);
    return res.status(500).json({
      success: false,
      error: `Failed to initialize AI provider: ${error.message}`,
    });
  }
};

import { ZodError } from 'zod';

/**
 * Formats a ZodError into a structured array of field-level errors.
 *
 * Each element contains:
 *  - field  : dot-joined path (e.g. "preferences.jobRole")
 *  - message: human-readable description
 *
 * @param {ZodError} zodError
 * @returns {{ field: string, message: string }[]}
 */
const formatZodErrors = (zodError) =>
  (zodError.issues ?? zodError.errors).map((issue) => ({
    field: issue.path.join('.') || 'root',
    message: issue.message,
  }));

/**
 * Factory that returns an Express middleware validating the chosen part of the
 * request (body | query | params) against a Zod schema.
 *
 * On success the validated (and potentially transformed/defaulted) data is
 * written back to `req[target]` so downstream handlers receive clean data.
 *
 * On failure a structured 400 response is sent:
 * ```json
 * {
 *   "success": false,
 *   "error": "Validation failed",
 *   "details": [
 *     { "field": "title", "message": "Required" },
 *     { "field": "preferences.jobRole", "message": "Expected string, received number" }
 *   ]
 * }
 * ```
 *
 * @param {import('zod').ZodTypeAny} schema - Zod schema to validate against
 * @param {'body'|'query'|'params'} [target='body'] - which part of req to validate
 * @returns {import('express').RequestHandler}
 *
 * @example
 * import { validate } from '../middleware/validate.js';
 * import { createResumeSchema } from '../schemas/resume.schema.js';
 *
 * router.post('/', verifyToken, validate(createResumeSchema), asyncHandler(handler));
 */
export const validate = (schema, target = 'body') => {
  return (req, res, next) => {
    const result = schema.safeParse(req[target]);

    if (!result.success) {
      return res.status(400).json({
        success: false,
        error: 'Validation failed',
        details: formatZodErrors(result.error),
      });
    }

    // Replace req[target] with the parsed (possibly transformed) data
    req[target] = result.data;

    next();
  };
};

import express from "express";
import rateLimit from "express-rate-limit";
import { generateCoverLetter, extractResumeFromPDF } from "../services/coverLetterService.js";
import { verifyToken } from "../middleware/auth.js";
import PDFDocument from "pdfkit";

const router = express.Router();

// Max 10 cover-letter AI requests per user per 15 minutes to prevent quota abuse
const coverLetterLimiter = rateLimit({
  windowMs: 15 * 60 * 1000,
  max: 10,
  keyGenerator: (req) => req.user?.uid || req.ip,
  standardHeaders: true,
  legacyHeaders: false,
  handler: (_req, res) =>
    res.status(429).json({
      success: false,
      error: "Too many cover letter requests. Please wait before trying again.",
    }),
});

// POST /api/cover-letter/extract-resume
// Accepts base64 PDF and extracts resume text using Groq
router.post("/extract-resume", coverLetterLimiter, async (req, res) => {
  try {
    const { base64PDF } = req.body;
    if (!base64PDF) {
      return res.status(400).json({ error: "base64PDF is required" });
    }
    const resumeText = await extractResumeFromPDF(base64PDF);
    res.json({ resumeText });
  } catch (error) {
    console.error("Resume extraction error:", error);
    res.status(500).json({ error: "Failed to extract resume text" });
  }
});

// POST /api/cover-letter/generate-text
router.post("/generate-text", coverLetterLimiter, async (req, res) => {
  try {
    const { resumeText, jobDescription, companyName, hiringManager, tone } = req.body;

    if (!resumeText || !jobDescription) {
      return res.status(400).json({ error: "resumeText and jobDescription are required" });
    }

    const coverLetter = await generateCoverLetter({
      resumeText,
      jobDescription,
      companyName,
      hiringManager,
      tone,
    });

    res.json({ coverLetter });
  } catch (error) {
    console.error("Cover letter generation error:", error);
    res.status(500).json({ error: "Failed to generate cover letter" });
  }
});

// POST /api/cover-letter/download-pdf
router.post("/download-pdf", async (req, res) => {
  try {
    const { coverLetter, candidateName = "Candidate" } = req.body;
    if (!coverLetter) {
      return res.status(400).json({ error: "coverLetter is required" });
    }

    const doc = new PDFDocument({ margin: 72, size: "A4" });
    res.setHeader("Content-Type", "application/pdf");
    res.setHeader("Content-Disposition", `attachment; filename="cover-letter.pdf"`);
    doc.pipe(res);

    // Header styling
    doc.fontSize(11).font("Helvetica");

    const paragraphs = coverLetter.split(/\n+/).filter((p) => p.trim());
    paragraphs.forEach((para, i) => {
      if (i > 0) doc.moveDown(0.6);
      // Bold the subject line
      if (para.startsWith("Re:") || para.startsWith("Subject:")) {
        doc.font("Helvetica-Bold").text(para).font("Helvetica");
      } else if (para.startsWith("Sincerely") || para.startsWith("Best regards")) {
        doc.moveDown(0.5).text(para);
      } else {
        doc.text(para, { align: "justify", lineGap: 3 });
      }
    });

    doc.end();
  } catch (error) {
    console.error("PDF generation error:", error);
    res.status(500).json({ error: "Failed to generate PDF" });
  }
});

