// Overall feedback (post-interview)
// ---------------------------------------------------------------------------

export const generateOverallFeedback = async (interview, aiProvider) => {
  const answeredQuestions = interview.answers.length;
  const totalQuestions = interview.questions.length;

  const answersData = interview.answers.map((a) => ({
    question: a.question,
    relevance: a.analysis?.relevance || 0,
    clarity: a.analysis?.clarity || 0,
    confidence: a.analysis?.confidence || 0,
    expressionConfidence: a.expressionMetrics?.overallExpressionScore || 0,
    codeQuality: a.analysis?.codeAnalysis?.codeQuality || 0,
    hasCode: !!a.code
  }));

  const avgRelevance = answersData.reduce((sum, a) => sum + a.relevance, 0) / answersData.length || 0;
  const avgClarity = answersData.reduce((sum, a) => sum + a.clarity, 0) / answersData.length || 0;
  const avgConfidence = answersData.reduce((sum, a) => sum + a.confidence, 0) / answersData.length || 0;
  const avgExpression = answersData.reduce((sum, a) => sum + a.expressionConfidence, 0) / answersData.length || 0;
  const avgCodeQuality = answersData.filter(a => a.hasCode).reduce((sum, a) => sum + a.codeQuality, 0)
    / Math.max(1, answersData.filter(a => a.hasCode).length) || 0;

  const langDirective = languageDirective(interview.language || 'en');

  // Build prompt — note code-quality weight when interview is coding-mode
  const isCoding = interview.mode === 'coding';
  const prompt = `You are a senior interview coach providing overall feedback.

Interview Performance Data:
- Questions Answered: ${answeredQuestions}/${totalQuestions}
- Mode: ${interview.mode}
- Job Role: ${interview.jobRole}
- Experience Level: ${interview.experienceLevel}
- Average Relevance: ${avgRelevance.toFixed(1)}%
- Average Clarity: ${avgClarity.toFixed(1)}%
- Average Verbal Confidence: ${avgConfidence.toFixed(1)}%
- Average Expression Confidence: ${avgExpression.toFixed(1)}%
${isCoding ? `- Average Code Quality: ${avgCodeQuality.toFixed(1)}%` : ''}

Return ONLY valid JSON with this structure:
{
  "summary": "<3-4 sentence overall assessment>",
  "topStrengths": ["<strength 1>", "<strength 2>", "<strength 3>"],
  "areasToImprove": ["<area 1>", "<area 2>", "<area 3>"],
  "recommendations": ["<actionable recommendation 1>", "<recommendation 2>", "<recommendation 3>"],
  "expressionAnalysis": {
    "overallConfidence": ${avgExpression.toFixed(0)},
    "feedback": "<feedback on body language and confidence>"
  }
}${langDirective}`;

  const provider = aiProvider || getDefaultProvider();
  const result = await provider.generateContent(prompt);
  let cleanedText = result.text.replace(/```json\n?/g, '').replace(/```\n?/g, '').trim();
  const jsonMatch = cleanedText.match(/\{[\s\S]*\}/);
  if (jsonMatch) {
    cleanedText = jsonMatch[0];
  }

  let feedback;
  try {
    feedback = JSON.parse(cleanedText);
    if (!feedback || typeof feedback !== 'object') {
      throw new Error('Invalid feedback payload');
    }
  } catch (err) {
    console.error('Failed to parse overall feedback JSON:', err, cleanedText);
    throw new Error('Failed to generate overall feedback. Please try again.');
  }

  // Weight overall score differently for coding mode
  const overallScore = isCoding
    ? Math.round((avgRelevance * 0.25) + (avgClarity * 0.15) + (avgConfidence * 0.15) + (avgCodeQuality * 0.30) + (avgExpression * 0.15))
    : Math.round((avgRelevance * 0.35) + (avgClarity * 0.25) + (avgConfidence * 0.20) + (avgExpression * 0.20));

  return {
    overallScore,
    overallFeedback: feedback
  };
};

// ---------------------------------------------------------------------------
// Audio transcription (provider-routed)
// ---------------------------------------------------------------------------

/**
 * Transcribe an audio buffer using the user's BYOK provider.
 *
 * Provider strategy:
 *   - openai / openrouter (when model is whisper-1) → OpenAI audio.transcriptions
 *   - gemini → Gemini inline audio + prompt
 *   - groq → Groq's OpenAI-compatible /audio/transcriptions
 *
 * For providers without audio support we fall back to asking the LLM to
 * describe the audio (graceful degradation — will return a placeholder).
 */
export const transcribeAudio = async ({ audioBuffer, mimeType, language }, aiProvider) => {
  const provider = aiProvider || getDefaultProvider();
  const name = provider.providerName;

  // OpenAI / Groq / OpenRouter — all expose OpenAI-compatible audio endpoint
  if (name === 'openai' || name === 'groq' || name === 'openrouter') {
    if (!provider.client?.audio?.transcriptions?.create) {
      throw new Error('Selected provider does not support audio transcription. Switch to OpenAI or Groq.');
    }
    const file = new Blob([audioBuffer], { type: mimeType || 'audio/webm' });
    // Node's openai SDK expects a File-like object — build a minimal one
    const fileLike = {
      name: 'audio.webm',
      type: mimeType || 'audio/webm',
      arrayBuffer: async () => audioBuffer
    };
    const transcription = await provider.client.audio.transcriptions.create({
      file: fileLike,
      model: name === 'groq' ? 'whisper-large-v3-turbo' : 'whisper-1',
      language: language || undefined
    });
    return { text: transcription.text || '', language };
  }

  // Gemini — send audio inline
  if (name === 'gemini' && provider.model) {
    const result = await provider.model.generateContent({
      contents: [{
        role: 'user',
        parts: [
          { text: `Transcribe the following audio. Respond ONLY with the transcription, no commentary.${language ? ` Language: ${language}.` : ''}` },
          { inlineData: { mimeType: mimeType || 'audio/webm', data: Buffer.from(audioBuffer).toString('base64') } }
        ]
      }]
    });
    const text = result.response.text();
    return { text: text || '', language };
  }

  throw new Error('Audio transcription is not supported by the active provider. Please use OpenAI, Groq, OpenRouter (Whisper), or Gemini.');
};

// ---------------------------------------------------------------------------
// LLM-judged code execution (no sandbox — security via prompt isolation)
// ---------------------------------------------------------------------------

/**
 * Have the LLM evaluate the candidate's code against the problem's test cases.
 * Does NOT execute the code — the LLM judges whether the code is logically
 * correct and would pass each test case. This eliminates RCE risk while still
 * giving meaningful "test results".
 */
export const runCodeAgainstTests = async ({ code, language, problemStatement, testCases }, aiProvider) => {
  const provider = aiProvider || getDefaultProvider();
  const safeCases = (testCases || []).filter(tc => !tc.hidden).slice(0, 2);
  const prompt = `You are a senior engineer doing a code-review dry run. You will mentally trace the candidate's code against each visible test case.

PROBLEM:
${problemStatement}

LANGUAGE: ${language}

VISIBLE TEST CASES:
${safeCases.map((tc, i) => `${i + 1}. input=${tc.input}, expected=${tc.expected}`).join('\n')}

CANDIDATE'S CODE:
\`\`\`${language}
${String(code).substring(0, 8000)}
\`\`\`

Return ONLY valid JSON:
{
  "results": [
    { "input": "<copy of input>", "expected": "<copy of expected>", "actual": "<what the candidate's code would return>", "passed": <true|false> }
  ],
  "summary": "<one-sentence overall assessment>"
}

Rules:
1. Do NOT execute any code — reason about it carefully
2. Be honest — if the code is clearly wrong, mark passed: false
3. If the code is correct for some cases but not others, mark each case's passed individually
4. Treat edge cases (empty input, n=1, etc.) carefully`;

  const result = await provider.generateContent(prompt);
  let cleaned = (result.text || '').replace(/```json\n?/g, '').replace(/```\n?/g, '').trim();
  const m = cleaned.match(/\{[\s\S]*\}/);
  if (m) cleaned = m[0];
  try {
    return JSON.parse(cleaned);
  } catch (err) {
    console.error('Failed to parse run-code JSON:', err);
    throw new Error('Failed to evaluate code. Please try again.');
  }
};

import { aiCallsCounter } from '../middleware/metrics.js';

export const optimizeLinkedInProfile = async (profileText, targetRole, aiProvider) => {
    if (!aiProvider) {
        throw new Error('AI Provider is required. Please provide an API key.');
    }

    const prompt = `
    You are a world-class LinkedIn profile coach and career strategist. Analyze the following LinkedIn profile text and provide comprehensive optimization suggestions.

    LinkedIn Profile Text:
    ${profileText}

    Target Role / Industry (if provided): ${targetRole || 'General career growth'}

    Return ONLY a valid JSON object in the exact following format, without markdown codeblocks:
    {
        "overallScore": 72,
        "scoreBreakdown": {
            "headline": 60,
            "about": 70,
            "skills": 75,
            "overall": 72
        },
        "headlineSuggestions": [
            "Suggested Headline 1 — keyword-rich and role-specific",
            "Suggested Headline 2 — achievement-focused",
            "Suggested Headline 3 — value-proposition style"
        ],
        "aboutRewrite": "Full rewritten About/Summary section that is compelling, keyword-optimized, and written in first person...",
        "strengthsFound": ["Strength 1", "Strength 2", "Strength 3"],
        "quickWins": [
            { "action": "Specific quick improvement action", "impact": "High" }
        ],
        "skillsGapVsPeers": [
            { "skill": "Skill Name", "reason": "Why industry peers in this role typically list this skill" }
        ],
        "summary": "A brief 2-3 sentence overall assessment of the profile's strengths and key areas to improve."
    }

    Rules:
    - overallScore: Integer 0-100 based on completeness, keyword richness, and professionalism.
    - scoreBreakdown: Individual scores for headline, about section, and skills.
    - headlineSuggestions: 3 specific headline rewrites with strong action keywords for the target role.
    - aboutRewrite: A complete, professional rewrite of the About section (150-250 words).
    - strengthsFound: 3-5 strong points already present in the profile.
    - quickWins: 3-5 small, high-impact actions the user can take today. Impact must be "High", "Medium", or "Low".
    - skillsGapVsPeers: 3-5 skills commonly seen in top profiles for this role that are missing here.
    - summary: Concise overall feedback.
    `;

    try {
        const result = await aiProvider.generateContent(prompt);
        const text = result.text;

        // Strip markdown fences the model sometimes wraps output in
        const cleanedText = text.replace(/```json\n?/g, '').replace(/```\n?/g, '').trim();

        // Locate the JSON object boundaries to handle any extra prose
        const start = cleanedText.indexOf('{');
        const end = cleanedText.lastIndexOf('}');
        if (start === -1 || end === -1 || end <= start) {
            throw new Error('Model did not return a valid JSON object');
        }

        const parsed = JSON.parse(cleanedText.slice(start, end + 1));

        // Coerce overallScore if it is returned as a numeric string
        if (parsed && typeof parsed.overallScore === 'string') {
            const parsedNum = Number(parsed.overallScore);
            if (!isNaN(parsedNum)) {
                parsed.overallScore = parsedNum;
            }
        }

        // Validate the expected response shape
        const hasShape =
            typeof parsed?.overallScore === 'number' &&
            Array.isArray(parsed?.headlineSuggestions) &&
            typeof parsed?.aboutRewrite === 'string' &&
            Array.isArray(parsed?.strengthsFound) &&
            Array.isArray(parsed?.quickWins) &&
            Array.isArray(parsed?.skillsGapVsPeers);

        if (!hasShape) {
            throw new Error('Invalid LinkedIn optimizer response shape');
        }

        // Clamp scores to 0-100
        parsed.overallScore = Math.max(0, Math.min(100, Math.round(Number(parsed.overallScore) || 0)));
        if (parsed.scoreBreakdown && typeof parsed.scoreBreakdown === 'object' && !Array.isArray(parsed.scoreBreakdown)) {
            const keys = ['headline', 'about', 'skills', 'overall'];
            for (const key of keys) {
                const rawVal = parsed.scoreBreakdown[key] !== undefined ? parsed.scoreBreakdown[key] : parsed.overallScore;
                const val = Number(rawVal);
                parsed.scoreBreakdown[key] = isNaN(val) ? 0 : Math.max(0, Math.min(100, Math.round(val)));
            }
        } else {
            parsed.scoreBreakdown = { headline: parsed.overallScore, about: parsed.overallScore, skills: parsed.overallScore, overall: parsed.overallScore };
        }

        return parsed;

    } catch (error) {
        console.error('Error optimizing LinkedIn profile:', error);
        throw new Error('Failed to optimize LinkedIn profile.');
    }
};

import axios from 'axios';

const LINKEDIN_AUTH_URL = "https://www.linkedin.com/oauth/v2/authorization";
const LINKEDIN_TOKEN_URL = "https://www.linkedin.com/oauth/v2/accessToken";
const LINKEDIN_USERINFO_URL = "https://api.linkedin.com/v2/userinfo";

const { LINKEDIN_CLIENT_ID, LINKEDIN_CLIENT_SECRET, LINKEDIN_REDIRECT_URI } =
  process.env;

/**
 * Build LinkedIn authorization URL
 * @param {string} state - Random CSRF token
 */
export const getLinkedInAuthUrl = (state) => {
  const params = new URLSearchParams({
    response_type: "code",
    client_id: LINKEDIN_CLIENT_ID,
    redirect_uri: LINKEDIN_REDIRECT_URI,
    scope: "openid profile email",
    state,
  });
  return `${LINKEDIN_AUTH_URL}?${params.toString()}`;
};

/**
 * Exchange authorization code for access token
 * @param {string} code - Code from LinkedIn callback
 */
export const exchangeCodeForToken = async (code) => {
  const params = new URLSearchParams({
    grant_type: "authorization_code",
    code,
    redirect_uri: LINKEDIN_REDIRECT_URI,
    client_id: LINKEDIN_CLIENT_ID,
    client_secret: LINKEDIN_CLIENT_SECRET,
  });

  const response = await axios.post(LINKEDIN_TOKEN_URL, params.toString(), {
    headers: {
      "Content-Type": "application/x-www-form-urlencoded",
    },
  });

  return {
        accessToken: response.data.access_token,
        idToken: response.data.id_token,
    };
};

/**
 * Fetch LinkedIn user profile using OpenID Connect userInfo endpoint
 * @param {string} accessToken
 */
export const getLinkedInProfile = async (accessToken, idToken) => {
  const payload = JSON.parse(Buffer.from(idToken.split('.')[1], 'base64url').toString())

  return {
    linkedinId: payload.sub,
    email: payload.email,
    name: payload.name,
    picture: payload.picture || null,
  };
};

import { db } from '../config/firebase.js';
import { FieldValue } from 'firebase-admin/firestore';
import { presenceService } from './presenceService.js';

// Collection references
const channelsRef = db.collection('channels');
const messagesRef = db.collection('messages');
const postsRef = db.collection('posts');
const commentsRef = db.collection('comments');
const conversationsRef = db.collection('conversations');
const directMessagesRef = db.collection('directMessages');

export const setupSocketHandlers = (io, socket) => {
  const user = socket.user;

  socket.on('request_job_alerts_status', async () => {
    try {
      console.log(`📊 User ${user.email} requested job alerts status`);
      socket.emit('job_alerts_status', {
        message: 'Job alerts are active and monitoring',
        timestamp: new Date()
      });
    } catch (error) {
      console.error('Job alerts status error:', error);
    }
  });

  // ============ CHANNEL EVENTS ============

  // Join a channel
  socket.on('join_channel', async (channelId) => {
    try {
      const channelDoc = await channelsRef.doc(channelId).get();
      if (!channelDoc.exists) {
        socket.emit('error', { message: 'Channel not found' });
        return;
      }

      const channel = channelDoc.data();
      socket.join(`channel:${channelId}`);
      console.log(`${user.name} joined channel: ${channel.name}`);

      // Notify others in the channel
      socket.to(`channel:${channelId}`).emit('user_joined_channel', {
        channelId,
        user: { uid: user.uid, name: user.name }
      });

      // Fetch recent messages using indexed query
      let messages = [];
      try {
        const messagesSnapshot = await messagesRef
          .where('channelId', '==', channelId)
          .where('isDeleted', '==', false)
          .orderBy('createdAt', 'desc')
          .limit(50)
          .get();

        messages = messagesSnapshot.docs
          .map(doc => ({
            id: doc.id,
            ...doc.data(),
            createdAt: doc.data().createdAt?.toDate?.() || doc.data().createdAt
          }))
          .reverse();
      } catch (msgError) {
        console.error('Error fetching messages:', msgError.message);
        // Continue with empty messages array
      }

      socket.emit('channel_messages', {
        channelId,
        messages
      });
    } catch (error) {
      console.error('Join channel error:', error);
      socket.emit('error', { message: 'Failed to join channel' });
    }
  });

  // Leave a channel
  socket.on('leave_channel', (channelId) => {
    socket.leave(`channel:${channelId}`);
    socket.to(`channel:${channelId}`).emit('user_left_channel', {
      channelId,
      user: { uid: user.uid, name: user.name }
    });
  });

  // Send message to channel
  socket.on('send_message', async (data) => {
    try {
      const { channelId, content, replyTo, attachments, tempId } = data;

      if (!content || !content.trim()) {
        socket.emit('error', { message: 'Message content is required' });
        return;
      }

      // Create message data
      const messageData = {
        content: content.trim(),
        channelId,
        sender: {
          uid: user.uid,
          name: user.name,
          email: user.email,
          avatar: user.picture || null
        },
        messageType: 'text',
        attachments: attachments || [],
        reactions: [],
        mentions: [],
        replyTo: replyTo || null,
        replyToPreview: null,
        isEdited: false,
        isDeleted: false,
        isPinned: false,
        readBy: [],
        createdAt: FieldValue.serverTimestamp(),
        updatedAt: FieldValue.serverTimestamp()
      };

      // Add reply preview if replying
      if (replyTo) {
        const originalMessageDoc = await messagesRef.doc(replyTo).get();
        if (originalMessageDoc.exists) {
          const originalMessage = originalMessageDoc.data();
          messageData.replyToPreview = {
            content: originalMessage.content.substring(0, 100),
            senderName: originalMessage.sender.name
          };
        }
      }

      const docRef = await messagesRef.add(messageData);
      const savedMessage = {
        id: docRef.id,
        ...messageData,
        createdAt: new Date(),
        updatedAt: new Date()
      };

      // Update channel's last message (don't await - do in background)
      channelsRef.doc(channelId).update({
        lastMessage: {
          content: content.substring(0, 100),
          senderName: user.name,
          timestamp: new Date().toISOString()
        },
        updatedAt: FieldValue.serverTimestamp()
      }).catch(err => console.error('Failed to update channel lastMessage:', err));

      // Send confirmation to sender with tempId to replace optimistic message
      socket.emit('message_confirmed', {
        ...savedMessage,
        channelId,
        tempId
      });

      // Broadcast to OTHER users in channel (not the sender)
      socket.to(`channel:${channelId}`).emit('new_message', {
        ...savedMessage,
        channelId
      });

    } catch (error) {
      console.error('Send message error:', error);
      socket.emit('error', { message: 'Failed to send message' });
    }
  });

  // Typing indicator
  socket.on('typing_start', ({ channelId }) => {
    socket.to(`channel:${channelId}`).emit('user_typing', {
      channelId,
      user: { uid: user.uid, name: user.name }
    });
  });

  socket.on('typing_stop', ({ channelId }) => {
    socket.to(`channel:${channelId}`).emit('user_stopped_typing', {
      channelId,
      user: { uid: user.uid, name: user.name }
    });
  });

  // Add reaction to message
  socket.on('add_reaction', async ({ messageId, emoji }) => {
    try {
      let updatedReactions = null;
      let channelId = null;

      await messagesRef.firestore.runTransaction(async (tx) => {
        const messageRef = messagesRef.doc(messageId);
        const messageDoc = await tx.get(messageRef);
        if (!messageDoc.exists) return;

        const message = messageDoc.data();
        channelId = message.channelId;
        let reactions = message.reactions || [];

        // Find existing reaction with same emoji
        const reactionIndex = reactions.findIndex(r => r.emoji === emoji);

        if (reactionIndex >= 0) {
          // Check if user already reacted
          const userReacted = reactions[reactionIndex].users.some(u => u.uid === user.uid);
          if (!userReacted) {
            reactions[reactionIndex].users.push({ uid: user.uid, name: user.name });
          }
        } else {
          reactions.push({
            emoji,
            users: [{ uid: user.uid, name: user.name }]
          });
        }

        updatedReactions = reactions;
        tx.update(messageRef, { reactions });
      });

      if (channelId && updatedReactions) {
        io.to(`channel:${channelId}`).emit('message_reaction_updated', {
          messageId,
          reactions: updatedReactions
        });
      }
    } catch (error) {
      console.error('Add reaction error:', error);
    }
  });

  // Remove reaction
  socket.on('remove_reaction', async ({ messageId, emoji }) => {
    try {
      const messageDoc = await messagesRef.doc(messageId).get();
      if (!messageDoc.exists) return;

      const message = messageDoc.data();
      let reactions = message.reactions || [];

      const reactionIndex = reactions.findIndex(r => r.emoji === emoji);
      if (reactionIndex >= 0) {
        reactions[reactionIndex].users = reactions[reactionIndex].users.filter(u => u.uid !== user.uid);
        if (reactions[reactionIndex].users.length === 0) {
          reactions = reactions.filter(r => r.emoji !== emoji);
        }
      }

      await messagesRef.doc(messageId).update({ reactions });

      io.to(`channel:${message.channelId}`).emit('message_reaction_updated', {
        messageId,
        reactions
      });
    } catch (error) {
      console.error('Remove reaction error:', error);
    }
  });

  // Edit message
  socket.on('edit_message', async ({ messageId, content }) => {
    try {
      const messageDoc = await messagesRef.doc(messageId).get();
      if (!messageDoc.exists) {
        socket.emit('error', { message: 'Message not found' });
        return;
      }

      const message = messageDoc.data();
      if (message.sender.uid !== user.uid) {
        socket.emit('error', { message: 'Cannot edit this message' });
        return;
      }

      const editedAt = new Date();
      await messagesRef.doc(messageId).update({
        content,
        isEdited: true,
        editedAt: FieldValue.serverTimestamp()
      });

      io.to(`channel:${message.channelId}`).emit('message_edited', {
        messageId,
        content,
        editedAt
      });
    } catch (error) {
      console.error('Edit message error:', error);
    }
  });

  // Delete message
  socket.on('delete_message', async ({ messageId }) => {
    try {
      const messageDoc = await messagesRef.doc(messageId).get();
      if (!messageDoc.exists) {
        socket.emit('error', { message: 'Message not found' });
        return;
      }

      const message = messageDoc.data();
      if (message.sender.uid !== user.uid) {
        socket.emit('error', { message: 'Cannot delete this message' });
        return;
      }

      await messagesRef.doc(messageId).update({
        isDeleted: true,
        deletedAt: FieldValue.serverTimestamp()
      });

      io.to(`channel:${message.channelId}`).emit('message_deleted', { messageId });
    } catch (error) {
      console.error('Delete message error:', error);
    }
  });

  // ============ DIRECT MESSAGE EVENTS ============

  // Start or get conversation
  socket.on('start_conversation', async ({ receiverId, receiverName, receiverEmail }) => {
    try {
      // Check if conversation exists - search for both participants
      const existingSnapshot = await conversationsRef
        .where('participantIds', 'array-contains', user.uid)
        .get();

      let conversation = null;
      existingSnapshot.forEach(doc => {
        const data = doc.data();
        if (data.participantIds.includes(receiverId)) {
          conversation = { id: doc.id, ...data };
        }
      });

      if (!conversation) {
        const conversationData = {
          participants: [
            { uid: user.uid, name: user.name, email: user.email, avatar: user.picture || null },
            { uid: receiverId, name: receiverName, email: receiverEmail, avatar: null }
          ],
          participantIds: [user.uid, receiverId],
          lastMessage: null,
          unreadCount: {
            [user.uid]: 0,
            [receiverId]: 0
          },
          isActive: true,
          createdAt: FieldValue.serverTimestamp(),
          updatedAt: FieldValue.serverTimestamp()
        };

        const docRef = await conversationsRef.add(conversationData);
        conversation = { id: docRef.id, ...conversationData, createdAt: new Date(), updatedAt: new Date() };
      }

      socket.emit('conversation_started', { conversation });
    } catch (error) {
      console.error('Start conversation error:', error);
      socket.emit('error', { message: 'Failed to start conversation' });
    }
  });

  // Send direct message
  socket.on('send_direct_message', async ({ conversationId, receiverId, content }) => {
    try {
      const convDoc = await conversationsRef.doc(conversationId).get();
      if (!convDoc.exists) {
        socket.emit('error', { message: 'Conversation not found' });
        return;
      }

      const conversation = convDoc.data();
      const receiver = conversation.participants.find(p => p.uid === receiverId);

      const dmData = {
        conversationId,
        sender: {
          uid: user.uid,
          name: user.name,
          email: user.email,
          avatar: user.picture || null
        },
        receiver: {
          uid: receiverId,
          name: receiver?.name || 'Unknown'
        },
        content,
        messageType: 'text',
        attachments: [],
        isRead: false,
        isEdited: false,
        isDeleted: false,
        createdAt: FieldValue.serverTimestamp(),
        updatedAt: FieldValue.serverTimestamp()
      };

      const docRef = await directMessagesRef.add(dmData);
      const savedDm = { id: docRef.id, ...dmData, createdAt: new Date(), updatedAt: new Date() };

      // Update conversation
      const currentUnread = conversation.unreadCount?.[receiverId] || 0;
      await conversationsRef.doc(conversationId).update({
        lastMessage: {
          content: content.substring(0, 100),
          senderId: user.uid,
          senderName: user.name,
          timestamp: new Date().toISOString(),
          isRead: false
        },
        [`unreadCount.${receiverId}`]: currentUnread + 1,
        updatedAt: FieldValue.serverTimestamp()
      });

      // Get updated conversation
      const updatedConvDoc = await conversationsRef.doc(conversationId).get();
      const updatedConversation = { id: updatedConvDoc.id, ...updatedConvDoc.data() };

      // Send to both users
      io.to(`user:${user.uid}`).to(`user:${receiverId}`).emit('new_direct_message', {
        message: savedDm,
        conversation: updatedConversation
      });

    } catch (error) {
      console.error('Send DM error:', error);
      socket.emit('error', { message: 'Failed to send message' });
    }
  });

  // Mark messages as read
  socket.on('mark_messages_read', async ({ conversationId }) => {
    try {
      // Get unread messages for this user
      const unreadSnapshot = await directMessagesRef
        .where('conversationId', '==', conversationId)
        .where('receiver.uid', '==', user.uid)
        .where('isRead', '==', false)
        .get();

      // Update each message
      const batch = db.batch();
      unreadSnapshot.forEach(doc => {
        batch.update(doc.ref, { isRead: true, readAt: FieldValue.serverTimestamp() });
      });
      await batch.commit();

      // Reset unread count
      await conversationsRef.doc(conversationId).update({
        [`unreadCount.${user.uid}`]: 0
      });

      socket.emit('messages_marked_read', { conversationId });
    } catch (error) {
      console.error('Mark read error:', error);
    }
  });

  // DM typing indicator
  socket.on('dm_typing_start', ({ conversationId, receiverId }) => {
    io.to(`user:${receiverId}`).emit('dm_user_typing', {
      conversationId,
      user: { uid: user.uid, name: user.name }
    });
  });

  socket.on('dm_typing_stop', ({ conversationId, receiverId }) => {
    io.to(`user:${receiverId}`).emit('dm_user_stopped_typing', {
      conversationId,
      user: { uid: user.uid, name: user.name }
    });
  });

  // ============ POST/DISCUSSION EVENTS ============

  // New post notification
  socket.on('subscribe_posts', () => {
    socket.join('posts:feed');
  });

  socket.on('unsubscribe_posts', () => {
    socket.leave('posts:feed');
  });

  // Like post (real-time update)
  socket.on('like_post', async ({ postId }) => {
    try {
      let updatedLikes = null;
      let updatedLikeCount = null;

      await postsRef.firestore.runTransaction(async (tx) => {
        const postRef = postsRef.doc(postId);
        const postDoc = await tx.get(postRef);
        if (!postDoc.exists) return;

        const post = postDoc.data();
        const likes = post.likes || [];
        const alreadyLiked = likes.some(l => l.uid === user.uid);

        const likeData = { uid: user.uid, name: user.name, likedAt: new Date().toISOString() };
        const likeToRemove = likes.find(l => l.uid === user.uid);

        if (alreadyLiked) {
          updatedLikes = likes.filter(l => l.uid !== user.uid);
          updatedLikeCount = Math.max(0, (post.likeCount || likes.length) - 1);
        } else {
          updatedLikes = [...likes, likeData];
          updatedLikeCount = (post.likeCount || likes.length) + 1;
        }

        tx.update(postRef, {
          likes: updatedLikes,
          likeCount: updatedLikeCount
        });
      });

      if (updatedLikes) {
        io.to('posts:feed').emit('post_like_updated', {
          postId,
          likeCount: updatedLikeCount,
          likes: updatedLikes
        });
      }
    } catch (error) {
      console.error('Like post error:', error);
    }
  });

  // New comment notification
  socket.on('new_comment', async ({ postId, content, parentCommentId }) => {
    try {
      const postDoc = await postsRef.doc(postId).get();
      if (!postDoc.exists) return;

      const post = postDoc.data();

      const commentData = {
        content,
        postId,
        author: {
          uid: user.uid,
          name: user.name,
          email: user.email,
          avatar: user.picture || null
        },
        parentCommentId: parentCommentId || null,
        likes: [],
        likeCount: 0,
        replyCount: 0,
        isEdited: false,
        isDeleted: false,
        createdAt: FieldValue.serverTimestamp(),
        updatedAt: FieldValue.serverTimestamp()
      };

      const docRef = await commentsRef.add(commentData);
      const savedComment = { id: docRef.id, ...commentData, createdAt: new Date() };

      // Update comment count
      await postsRef.doc(postId).update({
        commentCount: FieldValue.increment(1)
      });

      // Update parent comment reply count if it's a reply
      if (parentCommentId) {
        await commentsRef.doc(parentCommentId).update({
          replyCount: FieldValue.increment(1)
        });
      }

      const newCommentCount = (post.commentCount || 0) + 1;

      io.to('posts:feed').emit('comment_added', {
        postId,
        comment: savedComment,
        commentCount: newCommentCount
      });

      // Notify post author if different user
      if (post.author.uid !== user.uid) {
        io.to(`user:${post.author.uid}`).emit('notification', {
          type: 'comment',
          message: `${user.name} commented on your post`,
          postId,
          timestamp: new Date()
        });
      }
    } catch (error) {
      console.error('New comment error:', error);
    }
  });

  // ============ PRESENCE EVENTS ============

  // Get online users
  socket.on('get_online_users', async () => {
    const onlineUsers = await presenceService.getOnlineUsers({ includeEmail: false });
    socket.emit('online_users', { users: onlineUsers });
  });

  // Update user status
  socket.on('update_status', async ({ status }) => {
    if (status === 'away') {
      await presenceService.setAway(user.uid);
    } else if (status === 'online') {
      await presenceService.setOnline(user.uid, user);
    }

    io.emit('user_status_changed', {
      uid: user.uid,
      status,
      timestamp: new Date()
    });
  });

  // ============ FELLOWSHIP CHAT EVENTS ============

  socket.on('join_fellowship_chat', ({ roomId }) => {
    socket.join(`fellowship:${roomId}`);
    console.log(`${user.name} joined fellowship chat: ${roomId}`);
  });

  socket.on('leave_fellowship_chat', ({ roomId }) => {
    socket.leave(`fellowship:${roomId}`);
  });

  socket.on('fellowship_message', ({ roomId, message }) => {
    socket.to(`fellowship:${roomId}`).emit('fellowship_message', {
      roomId,
      message
    });
  });

  socket.on('fellowship_typing_start', ({ roomId }) => {
    socket.to(`fellowship:${roomId}`).emit('fellowship_typing', {
      roomId,
      user: { uid: user.uid, name: user.name }
    });
  });

  socket.on('fellowship_typing_stop', ({ roomId }) => {
    socket.to(`fellowship:${roomId}`).emit('fellowship_stopped_typing', {
      roomId,
      user: { uid: user.uid, name: user.name }
    });
  });
};

