    'AWS Cloud Services'
  ],
  projects: [
    {
      title: 'DevFlow Platform',
      description: 'A developer workflow orchestrator built with Next.js and Go. Speeds up microservice deployment by 40% using automated environment templating.'
    },
    {
      title: 'SoundWave Web Client',
